// Turn a technical n8n error into a clean, friendly message for the user.
const exec = $json.execution || {};
const failedStep = exec.lastNodeExecuted || 'one of my steps';
const rawError = (exec.error && exec.error.message) ? exec.error.message : '';

// Map known failure points to plain-English explanations.
const friendly = {
  'OpenRouter Chat Model': "my thinking service didn't respond -- this is usually a temporary hiccup or a credit issue on OpenRouter",
  'Search Jobs Tool': "I couldn't reach the company job boards just now",
  'Search Indeed Tool': "I couldn't load the Indeed search just now",
  'Search Vault Memory': "I couldn't read my notes vault just now",
  'Fetch onQ Reminders': "I couldn't check your onQ deadlines",
  'Fetch Health Check': "I couldn't run my status check",
  'Fetch Job Deadline Reminders': "I couldn't check job application deadlines"
};

let reason = friendly[failedStep];
if (!reason) {
  if (/ECONNREFUSED|fetch failed|ETIMEDOUT|connect/i.test(rawError)) {
    reason = "I couldn't reach one of my helpers -- it may not be running yet";
  } else if (/credit|quota|402|payment|insufficient/i.test(rawError)) {
    reason = "my thinking service is out of credit -- topping up OpenRouter should fix it";
  } else {
    reason = "something went sideways on the '" + failedStep + "' step";
  }
}

const message = "Sorry master, I ran into a problem while working on that. \n\n" +
  "What happened: " + reason + ".\n\n" +
  "Please try again in a moment. If it keeps happening, let me know and I'll take a closer look.";

return [{ json: { message } }];
